// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Your Netlify site + /api (no trailing slash)
    site_api_url: "https://intake-ops-ai.netlify.app/api",
    // Must match INTAKEOPS_API_KEY in Netlify exactly
    intakeops_api_key: "PASTE_YOUR_INTAKEOPS_API_KEY",
    // Your n8n webhook base URL (used to hand missed calls to Lead Recovery)
    n8n_webhook_base: "https://billbotprocessing.app.n8n.cloud/webhook",
    // Used when the call doesn't say: plumbing, legal, med-spa, property-management or general
    default_industry: "general",
    // Calls shorter than this with no details collected count as missed calls
    missed_call_max_seconds: 45,
  },
}];

const req = $('Vapi Call Ended').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};

// Vapi also sends status updates etc. to the same URL — only handle the final report.
if (msg.type && msg.type !== 'end-of-call-report') return [];

const cfg = $('Config').first().json;
const artifact = msg.artifact ?? {};
const analysis = msg.analysis ?? call.analysis ?? {};
const data = analysis.structuredData ?? {};
const meta = call.metadata ?? {};
const pick = (...values) => values.find((v) => typeof v === 'string' && v.trim()) ?? '';

const startedAt = msg.startedAt ?? call.startedAt;
const endedAt = msg.endedAt ?? call.endedAt;
let duration = Math.round(Number(msg.durationSeconds ?? call.durationSeconds ?? 0));
if (!duration && startedAt && endedAt) {
  duration = Math.round((new Date(endedAt) - new Date(startedAt)) / 1000);
}

const urgencyRaw = pick(data.urgency_level, meta.urgency_level).toLowerCase();
const urgency = ['emergency', 'high', 'standard', 'unqualified'].includes(urgencyRaw) ? urgencyRaw : 'standard';
const industryRaw = pick(data.industry, meta.industry, cfg.default_industry).toLowerCase();
const industry = ['plumbing', 'legal', 'med-spa', 'property-management', 'general'].includes(industryRaw) ? industryRaw : 'general';

const lead = {
  call_id: pick(call.id, msg.callId) || `vapi-${Date.now()}`,
  caller_phone: pick(call.customer?.number, msg.customer?.number, data.caller_phone),
  caller_name: pick(data.caller_name, meta.caller_name) || 'Unknown',
  issue_description: pick(data.issue_description, meta.issue_description, analysis.summary),
  urgency_level: urgency,
  service_address: pick(data.service_address, meta.service_address),
  industry,
  call_duration_seconds: Math.max(0, duration || 0),
  transcript: pick(artifact.transcript, msg.transcript, call.transcript),
  recording_url: pick(
    artifact.recordingUrl, artifact.recording?.mono?.combinedUrl, artifact.recording?.stereoUrl,
    msg.recordingUrl, call.recordingUrl,
  ),
  ended_reason: pick(msg.endedReason, call.endedReason),
  timestamp: new Date(startedAt || Date.now()).toISOString(),
};

// No details collected and a very short call: treat it as a missed call.
const collectedDetails = Boolean(pick(data.caller_name, data.issue_description, meta.caller_name));
const isMissed = !collectedDetails && lead.call_duration_seconds < Number(cfg.missed_call_max_seconds);

const TICKETS = {
  emergency: { priority: 'CRITICAL', status: 'escalated' },
  high: { priority: 'HIGH', status: 'pending_callback' },
  standard: { priority: 'NORMAL', status: 'queued' },
};
const ticket = TICKETS[urgency] ? { ...lead, ...TICKETS[urgency] } : null;

return [{
  json: {
    is_missed: isMissed,
    needs_ticket: Boolean(ticket),
    lead,
    ticket,
    missed: { call_id: lead.call_id, caller_phone: lead.caller_phone, missed_at: lead.timestamp },
  },
}];
